const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE';

// Slide 1: Title
const s1 = pres.addSlide();
s1.addText('团队协作：打造高效能团队', { x: 0.8, y: 1.8, w: 11, fontSize: 36, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s1.addText('构建信任 · 明确目标 · 持续改进', { x: 0.8, y: 3.0, w: 11, fontSize: 20, color: '555555', fontFace: '微软雅黑' });

// Slide 2: Why teamwork matters
const s2 = pres.addSlide();
s2.addText('为什么团队协作至关重要', { x: 0.8, y: 0.5, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s2.addText(
  '• 复杂问题需要多元视角与跨职能能力\n' +
  '• 协作能将个人产出放大为系统性成果\n' +
  '• 高信任团队的决策速度提升 40%+\n' +
  '• 员工敬业度与留存率显著高于孤立工作模式',
  { x: 0.8, y: 1.5, w: 11, fontSize: 18, lineSpacingMultiple: 1.5, fontFace: '微软雅黑' }
);

// Slide 3: Core pillars
const s3 = pres.addSlide();
s3.addText('高效协作的四大支柱', { x: 0.8, y: 0.5, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s3.addText(
  '1. 共同目标 — 对齐愿景，让每个人知道"为什么做"\n' +
  '2. 心理安全 — 鼓励表达异议与试错，消除沉默成本\n' +
  '3. 清晰角色 — RACI 矩阵减少灰色地带与重复劳动\n' +
  '4. 反馈闭环 — 定期回顾、数据驱动、快速迭代',
  { x: 0.8, y: 1.5, w: 11, fontSize: 18, lineSpacingMultiple: 1.5, fontFace: '微软雅黑' }
);

// Slide 4: Common pitfalls & solutions
const s4 = pres.addSlide();
s4.addText('常见障碍与应对策略', { x: 0.8, y: 0.5, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s4.addTable([
  [{ text: '障碍', options: { bold: true, color: 'FFFFFF', fill: { color: '1B4F72' } } },
   { text: '应对策略', options: { bold: true, color: 'FFFFFF', fill: { color: '1B4F72' } } }],
  ['信息孤岛', '建立共享知识库 + 每周同步会'],
  ['责任模糊', 'RACI 矩阵 + 里程碑验收人签字'],
  ['冲突回避', '引入结构化复盘（AAR）+ 中立引导师'],
  ['远程协作疲劳', '异步优先 + 摄像头可选 + 聚焦议程']
], { x: 0.8, y: 1.5, w: 11, fontSize: 16, border: { pt: 0.5, color: 'CCCCCC' }, colW: [3.5, 7.5], fontFace: '微软雅黑' });

// Slide 5: Action plan & takeaway
const s5 = pres.addSlide();
s5.addText('下一步行动', { x: 0.8, y: 0.5, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s5.addText(
  '✅ 本周：完成团队 RACI 梳理并公示\n' +
  '✅ 本月：启动首次心理安全匿名调研\n' +
  '✅ 本季度：建立月度回顾机制，追踪协作指标\n\n' +
  '核心记忆：好的协作不是"人多"，而是"心齐、路清、反馈快"。',
  { x: 0.8, y: 1.5, w: 11, fontSize: 18, lineSpacingMultiple: 1.5, fontFace: '微软雅黑' }
);

pres.writeFile({ fileName: '/workspace/团队协作.pptx' }).then(() => console.log('done'));
